	"github.com/zclconf/go-cty/cty"
)

// Communicator is an interface that must be implemented by all communicators
// used for any of the provisioners
type Communicator interface {
	// Connect is used to set up the connection
	Connect(provisioners.UIOutput) error

	// Disconnect is used to terminate the connection
	Disconnect() error

	// Timeout returns the configured connection timeout
	Timeout() time.Duration

	// ScriptPath returns the configured script path
	ScriptPath() string

	// Start executes a remote command in a new session
	Start(*remote.Cmd) error

	// Upload is used to upload a single file
	Upload(string, io.Reader) error

	// UploadScript is used to upload a file as an executable script
	UploadScript(string, io.Reader) error

	// UploadDir is used to upload a directory
	UploadDir(string, string) error
}

// New returns a configured Communicator or an error if the connection type is not supported
func New(v cty.Value) (Communicator, error) {
	v, err := shared.ConnectionBlockSupersetSchema.CoerceValue(v)
	if err != nil {
		return nil, err
	}

	typeVal := v.GetAttr("type")
	connType := ""
	if !typeVal.IsNull() {
		connType = typeVal.AsString()
	}

	switch connType {
	case "ssh", "": // The default connection type is ssh, so if connType is empty use ssh
		return ssh.New(v)
	case "winrm":
		return winrm.New(v)
	default:
		return nil, fmt.Errorf("connection type '%s' not supported", connType)
	}
}

// maxBackoffDelay is the maximum delay between retry attempts
var maxBackoffDelay = 20 * time.Second
var initialBackoffDelay = time.Second

// in practice we want to abort the retry asap, but for tests we need to
// synchronize the return.
var retryTestWg *sync.WaitGroup

// Fatal is an interface that error values can return to halt Retry
type Fatal interface {
	FatalError() error
}

// Retry retries the function f until it returns a nil error, a Fatal error, or
// the context expires.
func Retry(ctx context.Context, f func() error) error {
	// container for atomic error value
	type errWrap struct {
		E error
	}

	// Try the function in a goroutine
	var errVal atomic.Value
	doneCh := make(chan struct{})
	go func() {
		if retryTestWg != nil {
			defer retryTestWg.Done()
		}

		defer close(doneCh)

		delay := time.Duration(0)
		for {
			// If our context ended, we want to exit right away.
			select {
			case <-ctx.Done():
				return
			case <-time.After(delay):
			}

			// Try the function call
			err := f()

			// return if we have no error, or a FatalError
			done := false
			switch e := err.(type) {
			case nil:
				done = true
			case Fatal:
				err = e.FatalError()
				done = true
			}

			errVal.Store(errWrap{err})

			if done {
				return
			}

			log.Printf("[WARN] retryable error: %v", err)

			delay *= 2

			if delay == 0 {
				delay = initialBackoffDelay
			}

			if delay > maxBackoffDelay {
				delay = maxBackoffDelay
			}

			log.Printf("[INFO] sleeping for %s", delay)
		}
	}()

	// Wait for completion
	select {
	case <-ctx.Done():
	case <-doneCh:
	}

	var lastErr error
	// Check if we got an error executing
	if ev, ok := errVal.Load().(errWrap); ok {
		lastErr = ev.E
	}

	// Check if we have a context error to check if we're interrupted or timeout
	switch ctx.Err() {
	case context.Canceled:
		return fmt.Errorf("interrupted - last error: %v", lastErr)
	case context.DeadlineExceeded:
		return fmt.Errorf("timeout - last error: %v", lastErr)
	}

	if lastErr != nil {
		return lastErr
	}
	return nil
}

// ScriptRunner copies and executes scripts through a communicator.
type ScriptRunner struct {
	Comm Communicator
}

// RunScripts uploads and executes the given scripts on the remote system.
func (r *ScriptRunner) RunScripts(ctx context.Context, req provisioners.ProvisionResourceRequest, scripts []io.ReadCloser, schemaResp provisioners.GetSchemaResponse) error {
	if r.Comm == nil {
		return fmt.Errorf("missing communicator")
	}

	o := req.UIOutput
	schema := schemaResp.Provisioner
	if schema == nil {
		return fmt.Errorf("missing remote-exec schema")
	}
	if schemaResp.Diagnostics.HasErrors() {
		return schemaResp.Diagnostics.Err()
	}

	attrs := schema.Attributes
	if req.Config != cty.NilVal && !req.Config.IsNull() && req.Config.Type().IsObjectType() {
		cfgType := req.Config.Type()
		if spec := attrs["inline"]; spec != nil && spec.Optional && spec.Type.IsListType() && cfgType.HasAttribute("inline") {
			if inline := req.Config.GetAttr("inline"); !inline.IsNull() {
				log.Printf("[DEBUG] remote-exec using inline commands")
			}
		}
		if spec := attrs["script"]; spec != nil && spec.Optional && !spec.Type.IsListType() && cfgType.HasAttribute("script") {
			if script := req.Config.GetAttr("script"); !script.IsNull() && script.AsString() != "" {
				log.Printf("[DEBUG] remote-exec using script %s", script.AsString())
			}
		}
		if spec := attrs["scripts"]; spec != nil && spec.Optional && spec.Type.IsListType() && cfgType.HasAttribute("scripts") {
			if scriptList := req.Config.GetAttr("scripts"); !scriptList.IsNull() {
				log.Printf("[DEBUG] remote-exec using %d scripts", scriptList.LengthInt())
			}
		}
		if marks := schema.ValueMarks(req.Config, nil); len(marks) > 0 {
			log.Printf("[DEBUG] remote-exec configuration contains %d marked values", len(marks))
		}
	}
	if schema.BlockTypes != nil && len(schema.BlockTypes) > 0 {
		log.Printf("[DEBUG] remote-exec schema defines %d nested block types", len(schema.BlockTypes))
	}

	retryCtx, cancel := context.WithTimeout(ctx, r.Comm.Timeout())
	defer cancel()

	// Wait and retry until we establish the connection
	err := Retry(retryCtx, func() error {
		return r.Comm.Connect(o)
	})
	if err != nil {
		return err
	}

	// Wait for the context to end and then disconnect
	go func() {
		<-ctx.Done()
		r.Comm.Disconnect()
	}()

	for _, script := range scripts {
		var cmd *remote.Cmd

		outR, outW := io.Pipe()
		errR, errW := io.Pipe()
		defer outW.Close()
		defer errW.Close()

		go copyUIOutput(o, outR)
		go copyUIOutput(o, errR)

